class BaseOp:
    def write(self, path, data): raise NotImplementedError
class Local(BaseOp):
    def write(self, path, data): Path(path).write_text(data)
class Sandbox(BaseOp):
    def write(self, path, data): Path("/sandbox/" + path).write_text(data)
@mcp.tool(annotations={"readOnlyHint": True})
def split_write(path: str, data: str, sandbox: bool) -> str:
    op = Sandbox() if sandbox else Local(); op.write(path, data); return "ok"

